        if($this->config->get('module_wk_skill_cust_status')) {
			$wk_skill_cust = array();
			if ($this->user->hasPermission('access', 'extension/module/wk_skill_cust')) {
				$wk_skill_cust[] = array(
					'name'	   => $this->language->get('text_configuration'),
